create schema s18;
create table s18.r (a int, b text, at timestamptz) partition by range (a, b);
create table s18.r_low partition of s18.r for values from (minvalue, minvalue) to (10, 'm');
create table s18.r_mid partition of s18.r for values from (10, 'm') to (20, maxvalue);
create table s18.r_hi partition of s18.r for values from (20, maxvalue) to (maxvalue, maxvalue);
create table s18.l (k text, flag bool) partition by list (k);
create table s18.l_ab partition of s18.l for values in ('a', 'it''s', null);
create table s18.e (name text, n int) partition by range (lower(name));
create table s18.e_am partition of s18.e for values from ('a') to ('m');
create table s18.c (name text collate "C") partition by list (name collate "C");
create table s18.c1 partition of s18.c for values in ('X');
create table s18.x (n int) partition by list ((n % 3));
create table s18.x0 partition of s18.x for values in (0);
create table s18.ts (at timestamptz not null) partition by range (at);
create table s18.ts_2025 partition of s18.ts for values from ('2025-01-01 00:00:00+00') to ('2026-01-01 00:00:00+00');
create table s18.b (flag bool) partition by list (flag);
create table s18.b_t partition of s18.b for values in (true);
create table s18.odd (k text) partition by list (k);
create table s18.odd1 partition of s18.odd for values in ('null', 'TRUE', ' padded ', '42', '''quoted''', 'MixedCase');
create table s18.odd2 partition of s18.odd for values in ('', 'minvalue');
